import 'package:dm_core_types/dm_core_types.dart';
import 'package:geo_salah_core/src/model/prayer_profile.dart';
import 'package:geo_salah_core/src/profile/prayer_profile_mapper.dart';
import 'package:geo_salah_core/src/wire/profile/prayer_profile_document.dart';
import 'package:json_annotation/json_annotation.dart';

/// The profiles the bench knows (§15 D29, D48): `bench/profiles/*.json`.
///
/// Each file is the compiled JSON of a seed profile in the repository's
/// `profiles/` (S07, Appendix A), generated by `geo_salah_profiles`'s
/// `tool/sync_bench_profiles.dart` and checked fresh by its tests. It is
/// read through the same `prayer_profile.v1` model and [PrayerProfileMapper]
/// as the app's profiles, so no value is written here (§0.2 rule 1). The
/// callers (`bin/bench.dart`, the golden tool and the tests) read the files;
/// this class does no I/O.
abstract final class BenchProfiles {
  /// The compiled profiles' directory, relative to the package root.
  static const String directory = 'bench/profiles';

  /// The id of the engine's fallback profile (ADR-007).
  static const String engineDefaultId = 'engine.default';

  /// The profiles of the decoded JSON [documents], by id.
  ///
  /// Throws [FormatException] for a document that is not a
  /// `prayer_profile.v1` profile, one the mapper refuses, or a repeated id.
  static Map<String, PrayerProfile> byId(Iterable<Object?> documents) {
    final profiles = <String, PrayerProfile>{};
    for (final document in documents) {
      final profile = _read(document);
      if (profiles.containsKey(profile.profileId)) {
        throw FormatException('Profile ${profile.profileId} appears twice');
      }
      profiles[profile.profileId] = profile;
    }
    return Map.unmodifiable(profiles);
  }

  static PrayerProfile _read(Object? json) {
    final PrayerProfileDocument document;
    try {
      document = switch (json) {
        final Map<String, Object?> object => PrayerProfileDocument.fromJson(
          object,
        ),
        _ => throw const FormatException('A profile is not a JSON object'),
      };
    } on CheckedFromJsonException catch (e) {
      throw FormatException('Not a prayer_profile.v1 document: ${e.message}');
    }
    return switch (PrayerProfileMapper.map(document)) {
      Ok(:final value) => value,
      Err(:final failure) => throw FormatException(failure.detail),
    };
  }
}
